# Construct objects (including their attached 2 markers), apply inferred translations.
objs={}
def add_obj(name, color, cells, marks, shift):
    dr,dc=shift
    objs[name]=[(r+dr,c+dc,color) for r,c in cells]+[(r+dr,c+dc,2) for r,c in marks]
# 6
c6={(2,12)}|{(3,c) for c in range(12,16)}|{(r,12) for r in range(4,7)}|{(6,c) for c in range(13,16)}|{(7,12)}
m6={(2,11),(3,16),(6,16),(7,11)}
# 8
c8={(r,4) for r in range(8,14)}; m8={(8,5),(13,5)}
# 4
c4={(r,c) for r in range(12,17) for c in range(11,15)}; m4={(11,14),(15,10),(16,15),(17,11)}
# 5
c5={(19,2),(19,3),(20,2),(21,2),(22,2),(22,5),(23,2),(23,5)}|{(24,c) for c in range(2,6)}|{(21,5),(23,5)}
m5={(19,4),(20,1),(21,5),(23,1)}
# 7
c7={(18,c) for c in range(16,20)}|{(19,16),(19,19),(20,16),(20,19),(21,19),(22,18),(22,19)}
m7={(18,15),(20,15),(21,16),(22,17)}
# 9 both components
c9={(3,c) for c in range(21,25)}|{(r,24) for r in range(4,9)}|{(9,23),(9,24)}|{(13,22),(13,23),(14,22),(15,22),(15,23)}
m9={(3,25),(4,21),(9,22),(13,24),(15,24)}
# translations relative to color 6 anchor
shifts={'6':(0,0),'8':(-6,6),'5':(-17,15),'4':(-13,9),'9':(-6,2),'7':(-15,9)}
add_obj('6',6,c6,m6,shifts['6']); add_obj('8',8,c8,m8,shifts['8']); add_obj('5',5,c5,m5,shifts['5']); add_obj('4',4,c4,m4,shifts['4']); add_obj('9',9,c9,m9,shifts['9']); add_obj('7',7,c7,m7,shifts['7'])
allcells=[p for v in objs.values() for p in v]
min(r for r,c,k in allcells),max(r for r,c,k in allcells),min(c for r,c,k in allcells),max(c for r,c,k in allcells)

anchor=(13,-9)
anch_shifts={k:(v[0]+anchor[0],v[1]+anchor[1]) for k,v in shifts.items()}
anch_shifts

objs={}
for nm,col,cells,marks in [('6',6,c6,m6),('8',8,c8,m8),('5',5,c5,m5),('4',4,c4,m4),('9',9,c9,m9),('7',7,c7,m7)]: add_obj(nm,col,cells,marks,anch_shifts[nm])
out=[[0]*26 for _ in range(26)]; conflicts=[]
for vals in objs.values():
 for r,c,k in vals:
  if not (0<=r<26 and 0<=c<26): conflicts.append(('bound',r,c,k));continue
  old=out[r][c]
  if old not in (0,k) and old!=2 and k!=2: conflicts.append(('color',r,c,old,k))
  if k!=2 or old==0: out[r][c]=k
print(conflicts)
print('rows',sum(any(x for x in row) for row in out))
print('\n'.join(' '.join(map(str,row)) for row in out))

# Build candidate treating the two disconnected 9 blobs independently; connect the main blob to 4, and the satellite blob/7 to a compatible marker pair.
t6=(13,-9);t8=(7,-3);t5=(-4,6);t4=(0,0); t9main=(7,-7); t7=(-11,2); t9sat=(-6,-7)
# split 9 cells and marker assignments
c9main={(3,c) for c in range(21,25)}|{(r,24) for r in range(4,9)}|{(9,23),(9,24)}
m9main={(3,25),(4,21),(9,22)}
c9sat={(13,22),(13,23),(14,22),(15,22),(15,23)};m9sat={(13,24),(15,24)}
parts=[('6',6,c6,m6,t6),('8',8,c8,m8,t8),('5',5,c5,m5,t5),('4',4,c4,m4,t4),('9m',9,c9main,m9main,t9main),('9s',9,c9sat,m9sat,t9sat),('7',7,c7,m7,t7)]
gridcand=[[0]*26 for _ in range(26)]; conf=[]
for name,col,cells,marks,(dr,dc) in parts:
 for r,c in cells:
  r+=dr;c+=dc
  if gridcand[r][c] not in (0,col): conf.append((name,r,c,gridcand[r][c],col))
  gridcand[r][c]=col
 for r,c in marks:
  r+=dr;c+=dc
  if gridcand[r][c]==0:gridcand[r][c]=2
print('conflicts',conf)
print('\n'.join(' '.join(map(str,row)) for row in gridcand))

pieces={'6':m6,'8':m8,'4':m4,'5':m5,'7':m7,'9a':m9main,'9b':m9sat}
def shifts_overlaps(pa,pb):
 # tB relative to A yielding overlap of markers
 out={}
 for ar,ac in pa:
  for br,bc in pb:
   t=(ar-br,ac-bc)
   count=sum((r+t[0],c+t[1]) in pa for r,c in pb)
   if count>=2: out[t]=count
 return sorted(out.items(),key=lambda kv:(-kv[1],kv[0]))
for a in pieces:
 for b in pieces:
  if a<b:
   opts=shifts_overlaps(pieces[a],pieces[b])
   if opts: print(a,b,opts)

# enumerate candidate translations: 4->9a pair overlaps, one remaining 9a marker overlays either of 7's unused markers; 9b overlays 7's pair.
opts=shifts_overlaps(m4,m9main)
for t9,n in opts:
 rem=[(r+t9[0],c+t9[1]) for r,c in m9main if (r+t9[0],c+t9[1]) not in m4]
 print('9 shift',t9,'remaining',rem)
 for mr7 in [(21,16),(22,17)]:
  for p9 in rem:
   t7=(p9[0]-mr7[0],p9[1]-mr7[1]);t9b=(t7[0]+5,t7[1]-9)
   # test collisions against fixed translated objects
   placements=[('4',c4,t4),('5',c5,t5),('6',c6,t6),('8',c8,t8),('9a',c9main,t9),('9b',c9sat,t9b),('7',c7,t7)]
   occ={};coll=[]
   for nm,cells,t in placements:
    for r,c in cells:
     pos=(r+t[0],c+t[1])
     if pos in occ: coll.append((pos,occ[pos],nm))
     occ[pos]=nm
   print('7 marker',mr7,'t7',t7,'t9b',t9b,'collisions',coll[:3], 'bounds', min(r for r,c in occ),max(r for r,c in occ),min(c for r,c in occ),max(c for r,c in occ))

t7alt=(-12,1);t9salt=(-7,-8)
parts_alt=[('6',6,c6,m6,(13,-9)),('8',8,c8,m8,(7,-3)),('5',5,c5,m5,(-4,6)),('4',4,c4,m4,(0,0)),('9m',9,c9main,m9main,(7,-7)),('9s',9,c9sat,m9sat,t9salt),('7',7,c7,m7,t7alt)]
gridalt=[[0]*26 for _ in range(26)];conf=[]
for nm,col,cells,marks,(dr,dc) in parts_alt:
 for r,c in cells:
  r+=dr;c+=dc
  if gridalt[r][c] not in (0,col):conf.append((r,c,nm,col,gridalt[r][c]))
  gridalt[r][c]=col
 for r,c in marks:
  r+=dr;c+=dc
  if gridalt[r][c]==0:gridalt[r][c]=2
print(len(gridalt),{len(x) for x in gridalt},conf)
print('\n'.join(' '.join(map(str,row)) for row in gridalt[:18]))
